def cantor_numbering(N: int) -> str:
    d = 1
    while d * (d + 1) // 2 < N:
        d += 1
    prev_total = d * (d - 1) // 2
    p = N - prev_total
    if d % 2 == 0:
        numerator = p
        denominator = d + 1 - p
    else:
        numerator = d + 1 - p
        denominator = p
    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting K multiplication signs into the number string.

    :param num_str: A string of digits representing the number.
    :param N: Length of the number string.
    :param K: Number of multiplication signs to insert.
    :return: The maximum product as an integer.
    """
    if K < 0 or N == 0:
        return 0
    if K == 0:
        return int(num_str)
    if K > N - 1:
        return 0

    # Precompute integer values of all substrings num_str[j:i]
    sub_int = [[0] * (N + 1) for _ in range(N)]
    for j in range(N):
        num = 0
        for i in range(j + 1, N + 1):
            num = num * 10 + int(num_str[i - 1])
            sub_int[j][i] = num

    # dp[i][k] = maximum product for first i digits with k multiplication signs
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplication signs
    for i in range(1, N + 1):
        dp[i][0] = sub_int[0][i]

    # Fill DP table
    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):  # need at least k+1 digits to place k signs
            best = 0
            for j in range(k, i):
                prod = dp[j][k - 1] * sub_int[j][i]
                if prod > best:
                    best = prod
            dp[i][k] = best

    return dp[N][K]

