def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient part
        if abs_coeff == 1 and degree != 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    reverse = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o
        if o in reverse:
            if reverse[o] != e:
                return "Failed"
        else:
            reverse[o] = e
    if len(mapping) != 26:
        return "Failed"
    decoded = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded.append(mapping[ch])
    return ''.join(decoded)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    Parameters:
    x0 (int): The required greatest common divisor of the pair.
    y0 (int): The required least common multiple of the pair.

    Returns:
    int: The number of valid ordered pairs (P, Q).
    """
    # Quick checks for invalid inputs
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    m = y0 // x0  # product of the co-prime factors a and b

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= m:
        if m % i == 0:
            a = i
            b = m // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

def string_transformation(A, B, rules):
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns the minimum number of steps if possible,
    otherwise returns "NO ANSWER!".
    """
    if A == B:
        return 0

    from collections import deque

    max_steps = 10
    queue = deque([(A, 0)])
    visited = {A}

    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping replacements

    return "NO ANSWER!"

def remaining_trees_after_clearing(l, areas):
    if not areas:
        return l
    # Ensure intervals are in correct order and clamp to road bounds
    processed = []
    for s, e in areas:
        if s > e:
            s, e = e, s
        # Clamp to [0, l]
        if e <= 0 or s >= l:
            continue
        s = max(s, 0)
        e = min(e, l)
        processed.append((s, e))
    if not processed:
        return l
    # Sort intervals by start
    processed.sort(key=lambda x: x[0])
    # Merge overlapping or contiguous intervals
    merged = []
    for s, e in processed:
        if not merged:
            merged.append([s, e])
        else:
            last_s, last_e = merged[-1]
            if s <= last_e:  # overlap or touch
                merged[-1][1] = max(last_e, e)
            else:
                merged.append([s, e])
    # Calculate total removed trees
    total_removed = sum(e - s for s, e in merged)
    remaining = l - total_removed
    return remaining if remaining >= 0 else 0

